#!/usr/bin/env python3
"""Serial bounded validation of the authenticated merged constructor packet."""
import hashlib,json,pathlib,subprocess,time,os
here=pathlib.Path(__file__).resolve().parent
repo=here.parents[3]
out=pathlib.Path(os.environ.get('VALIDATE_OUTPUT','/workspace/lane-evidence/constructor-transport/consolidation'));out.mkdir(parents=True,exist_ok=True)
config=here/'serial.toml'
commands=[('migration-per-file', 'lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/MachineRelV1.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/MachineRelV1.lean; lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/MachineRelNat.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/MachineRelNat.lean; lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Producer.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Producer.lean; lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Controls.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Controls.lean; lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/RelationControls.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/RelationControls.lean'), ('migration-mcp', 'export PATH=/workspace/solidity-lean/tests/helpers-20261104/constructor-transport/nat-migration-20261107/bin:$PATH; export LEAN_MCP_SERVER_CMD="/workspace/solidity-lean/.venv/bin/python -m lean_lsp_mcp --lean-project-path /workspace/solidity-lean"; export LEAN_MCP_START_WAIT=45 LEAN_MCP_TIMEOUT=90 LEAN_LSP_MAX_OPEN_FILES=1; trap "scripts/coord-tools/lean-mcp stop" EXIT; scripts/coord-tools/lean-mcp diag Solidity/Lowering/V08/HelperPackets/ConstructorTransport/MachineRelV1.lean; scripts/coord-tools/lean-mcp diag Solidity/Lowering/V08/HelperPackets/ConstructorTransport/MachineRelNat.lean; scripts/coord-tools/lean-mcp diag Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Producer.lean; scripts/coord-tools/lean-mcp diag Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Controls.lean; scripts/coord-tools/lean-mcp diag Solidity/Lowering/V08/HelperPackets/ConstructorTransport/RelationControls.lean'), ('migration-audit', 'lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml build ConstructorMigrationAudit'), ('migration-build', 'lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml build Solidity.Lowering.V08.HelperPackets.ConstructorTransport.RelationControls ConstructorTransportAudit'), ('runtime', 'lean --version; /workspace/.setup/tools/lean-4.24.0-linux/bin/lake --version; cat /sys/fs/cgroup/memory.max /sys/fs/cgroup/memory.swap.max'), ('independent-pins', 'lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml build ConstructorIndependentPins'), ('packet', 'lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml build ConstructorTransportAudit'), ('per-file', 'lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Source.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Source.lean; lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Target.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Target.lean; lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Producer.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Producer.lean; lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Controls.setup.json Solidity/Lowering/V08/HelperPackets/ConstructorTransport/Controls.lean'), ('axiom-pins', 'lake -f /workspace/solidity-lean/tests/helpers-20261104/constructor-transport/consolidation-20261107/serial.toml env lean --tstack=131072 -j1 --setup .lake/build/ir/AxiomPins.setup.json tests/helpers-20261104/constructor-transport/AxiomPins.lean'), ('compiler-controls', 'node tests/helpers-20261104/constructor-transport/compiler-control.cjs'), ('roots', 'bash scripts/coord-tools/register.sh --check'), ('fragments', 'bash scripts/coord-tools/fragments.sh --check'), ('module-map', 'python3 scripts/coord-tools/module-map.py origin/master'), ('axiom-inventory', 'node scripts/check-axiom-pins.mjs'), ('trust', 'bash scripts/check-trust.sh'), ('layers', 'node scripts/check-layers.mjs'), ('orphans', 'node scripts/check-orphans.mjs'), ('doc-paths', 'bash scripts/check-doc-paths.sh')]
def available():
 host=int(next(s.split()[1] for s in pathlib.Path('/proc/meminfo').read_text().splitlines() if s.startswith('MemAvailable:')))*1024
 cg=pathlib.Path('/sys/fs/cgroup');limit=(cg/'memory.max').read_text().strip()
 return min(host,int(limit)-int((cg/'memory.current').read_text())) if limit!='max' else host
if os.environ.get("VALIDATE_ONLY"):
 commands=[x for x in commands if x[0] in os.environ["VALIDATE_ONLY"].split(",")]
results=[]
for name,cmd in commands:
 minimum=available()
 if minimum<4*1024**3:raise SystemExit('STOP: less than 4 GiB effective reserve')
 args=['docker','--host=unix:///var/run/docker.sock','run','--rm','--name','constructor-consolidation-gate','--memory=12g','--memory-swap=12g','--cpus=1','--user=1000:1000','-v','/workspace:/workspace','-v','/opt:/opt:ro','-v','/usr:/usr:ro','-w',str(repo),'ubuntu:24.04','bash','-c','set -eu; test "$(cat /sys/fs/cgroup/memory.max)" = 12884901888; test "$(cat /sys/fs/cgroup/memory.swap.max)" = 0; source /workspace/.setup/activate.sh; export LEAN_NUM_THREADS=1 LAKE_CACHE_DIR=/workspace/.setup/cache/lake; export PATH=/opt/codex/runtimes/codex-primary-runtime/dependencies/node/bin:$PATH; '+cmd]
 started=time.monotonic();stopped=False
 with (out/(name+'.log')).open('w') as log:
  log.write('COMMAND: '+cmd+'\n');log.flush()
  proc=subprocess.Popen(args,stdout=log,stderr=subprocess.STDOUT)
  while proc.poll() is None:
   minimum=min(minimum,available())
   if minimum<4*1024**3:
    subprocess.run(['docker','stop','constructor-consolidation-gate'],stdout=log,stderr=log);stopped=True
   time.sleep(.25)
 results.append({'name':name,'command':cmd,'status':'pass' if proc.returncode==0 and not stopped else 'fail','exit':proc.returncode,'seconds':round(time.monotonic()-started,3),'minimum_effective_available_bytes':minimum,'reserve_stop':stopped,'evidence':str(out/(name+'.log'))})
 (out/os.environ.get('VALIDATE_RESULTS','gates.json')).write_text(json.dumps(results,indent=2)+'\n')
 print(name,results[-1]['status'],flush=True)
